const logoMap: Record<string, LogoEntry> = {
  figma: { kind: 'svg', render: FigmaLogo },
  photoshop: { kind: 'svg', render: PhotoshopLogo },
  'untitled-ui': { kind: 'component', Component: UntitledUILogo },
  midjourney: { kind: 'svg', render: MidjourneyLogo },
  jitter: { kind: 'svg', render: JitterLogo },
  notion: { kind: 'svg', render: NotionLogo },
  clickup: { kind: 'svg', render: ClickUpLogo },
};

export default function ToolIcon({
  tool,
  size = 32,
  className,
}: Readonly<ToolIconProps>) {
  const entry = logoMap[tool];
  if (!entry) return null;

  if (entry.kind === 'component') {
    return <entry.Component className={className} size={size} />;
  }

  return (
    <svg
      viewBox="0 0 32 32"
      width={size}
      height={size}
      className={className}
      aria-label={tool}
    >
      <entry.render />
    </svg>
  );
}
